from hashlib import sha256

import pytest

from inline_snapshot.testing import Example


@pytest.mark.parametrize("flags", ["report", "fix"])
def test_normal_run_does_not_need_snapshot_catalog(storage_example, flags):
    storage_example(
        {
            ".inline-snapshot/custom/value.txt": "stored",
            "tests/test_something.py": """\
from inline_snapshot import external

def test_document():
    assert "stored" == external("custom:value.txt")
""",
        },
        backend="OfflineCatalogStorage",
    ).run_pytest(
        [f"--inline-snapshot={flags}"], outcomes={"passed": 1}, changed_files={}
    )


def test_trim_deletes_only_unreferenced_snapshots(storage_example):
    storage_example(
        {
            ".inline-snapshot/custom/value.txt": "stored",
            ".inline-snapshot/custom/unused.txt": "unused",
            "tests/test_something.py": """\
from inline_snapshot import external

def test_document():
    assert "stored" == external("custom:value.txt")
""",
        },
    ).run_pytest(
        ["--inline-snapshot=trim"],
        outcomes={"passed": 1},
        changed_files={".inline-snapshot/custom/unused.txt": None},
    )


def test_selected_tests_do_not_need_snapshot_catalog(storage_example):
    storage_example(
        {
            ".inline-snapshot/custom/value.txt": "stored",
            "tests/test_something.py": """\
from inline_snapshot import external

def test_selected():
    assert "stored" == external("custom:value.txt")

def test_other():
    assert "stored" == external("custom:value.txt")
""",
        },
        backend="OfflineCatalogStorage",
    ).run_pytest(
        ["-k", "test_selected"],
        env={"INLINE_SNAPSHOT_DEFAULT_FLAGS": "trim"},
        outcomes={"passed": 1, "deselected": 1},
        changed_files={},
    )


def test_trim_with_placeholder_in_skipped_test():
    used_digest = sha256(b"stored").hexdigest()
    unused_digest = sha256(b"unused").hexdigest()
    Example(
        {
            f".inline-snapshot/external/{used_digest}.txt": "stored",
            f".inline-snapshot/external/{unused_digest}.txt": "unused",
            "tests/test_something.py": f"""\
import pytest
from inline_snapshot import external

def test_document():
    assert "stored" == external("hash:{used_digest}.txt")

@pytest.mark.skip(reason="optional feature is not available")
def test_optional_feature():
    assert "new" == external("hash:")
""",
        }
    ).run_pytest(
        ["--inline-snapshot=trim"],
        outcomes={"passed": 1, "skipped": 1},
        changed_files={
            f".inline-snapshot/external/{unused_digest}.txt": None,
            ".inline-snapshot/files_using_external.txt": """\
# this file is generated by inline-snapshot and requires no manual edits (https://15r10nk.github.io/inline-snapshot/latest/external/external/#cleaning-up-old-externals)
tests/test_something.py
""",
        },
    )
